# CVE-2025-66471 (GHSA-2xpw-w6gg-jr37): streaming decompression bomb via urllib3 HTTPResponse.read
import gzip
import io
import zlib
from unittest import mock

import pytest
from urllib3.response import HTTPResponse

_RAW_LEN = 4 * 1024 * 1024  # 4 MiB of highly compressible (zero) data
_CHUNK = 65536  # typical application chunk size


def _make_gzip_bomb():
    raw = b"\x00" * _RAW_LEN
    buf = io.BytesIO()
    with gzip.GzipFile(filename="", mode="wb", fileobj=buf) as f:
        f.write(raw)
    return buf.getvalue(), _RAW_LEN


class _FakeConnection:
    def __init__(self, data):
        self._buf = io.BytesIO(data)

    def read(self, size=-1):
        return self._buf.read(size)


def _build_response(compressed):
    kwargs = dict(
        body=b"",
        headers={"content-encoding": "gzip"},
        status=200,
        preload_content=False,
        decode_content=True,
        connection=_FakeConnection(compressed),
    )
    try:
        kwargs["enforce_content_length"] = False
        return HTTPResponse(**kwargs)
    except TypeError:
        kwargs.pop("enforce_content_length", None)
        return HTTPResponse(**kwargs)


def test_streaming_read_does_not_decompress_entire_bomb():
    compressed, raw_len = _make_gzip_bomb()
    real_decompressobj = zlib.decompressobj
    holder = {"calls": 0, "max_output": 0}

    class _Wrapper:
        def __init__(self, real):
            self._real = real

        def decompress(self, data, max_length=None):
            holder["calls"] += 1
            if max_length is None:
                out = self._real.decompress(data)
            else:
                out = self._real.decompress(data, max_length)
            n = len(out)
            if n > holder["max_output"]:
                holder["max_output"] = n
            return out

        def __getattr__(self, name):
            return getattr(self._real, name)

    bound = max(_CHUNK, raw_len // 4)

    with mock.patch(
        "zlib.decompressobj",
        side_effect=lambda *a, **k: _Wrapper(real_decompressobj(*a, **k)),
    ):
        resp = _build_response(compressed)
        chunk = resp.read(_CHUNK)

    assert holder["calls"] > 0, "streaming path did not invoke the decompressor"
    assert len(chunk) == _CHUNK, "application should still receive the requested chunk"
    assert holder["max_output"] <= bound, (
        "decompression bomb not mitigated: a single decompress call emitted "
        f"{holder['max_output']} bytes (full payload {raw_len} bytes) to satisfy "
        f"a {_CHUNK}-byte read"
    )
